import { BrowserRouter, Routes, Route } from 'react-router-dom';
import Login from './pages/Login';
import AdminLogin from './pages/AdminLogin';
import AlumniRegistration from './pages/AlumniRegistration';
import ForgotPassword from './pages/ForgotPassword';
import ResetPassword from './pages/ResetPassword';
import AdminDashboard from './pages/AdminDashboard';
import AdminAlumniVerification from './pages/AdminAlumniVerification';
import AdminDocumentRequests from './pages/AdminDocumentRequests';
import AdminDocumentTracking from './pages/AdminDocumentTracking';
import Dashboard from './pages/Dashboard';
import AccountProfile from './pages/AccountProfile';
import DocumentRequest from './pages/DocumentRequest';
import DocumentTracking from './pages/DocumentTracking';
import Payment from './pages/Payment';
import PaymentReturn from './pages/PaymentReturn';
import PaymentMock from './pages/PaymentMock';
import PaymentReceipt from './pages/PaymentReceipt';
import RequestTracking from './pages/RequestTracking';
import ProtectedRoute from './components/ProtectedRoute';

function App() {
  return (
    <BrowserRouter>
      <Routes>
        <Route path="/" element={<Login />} />
        <Route path="/login" element={<Login />} />
        <Route path="/admin-login" element={<AdminLogin />} />
        <Route path="/forgot-password" element={<ForgotPassword />} />
        <Route path="/reset-password" element={<ResetPassword />} />
        <Route path="/alumni-registration" element={<AlumniRegistration />} />
        <Route
          path="/admin-dashboard"
          element={
            <ProtectedRoute roles={['admin']}>
              <AdminDashboard />
            </ProtectedRoute>
          }
        />
        <Route
          path="/admin-document-tracking"
          element={
            <ProtectedRoute roles={['admin']}>
              <AdminDocumentTracking />
            </ProtectedRoute>
          }
        />
        <Route
          path="/admin-document-requests"
          element={
            <ProtectedRoute roles={['admin']}>
              <AdminDocumentRequests />
            </ProtectedRoute>
          }
        />
        <Route
          path="/admin-alumni-verification"
          element={
            <ProtectedRoute roles={['admin']}>
              <AdminAlumniVerification />
            </ProtectedRoute>
          }
        />
        <Route
          path="/dashboard"
          element={
            <ProtectedRoute roles={['student', 'alumni']}>
              <Dashboard />
            </ProtectedRoute>
          }
        />
        <Route
          path="/account-profile"
          element={
            <ProtectedRoute roles={['student', 'alumni']}>
              <AccountProfile />
            </ProtectedRoute>
          }
        />
        <Route
          path="/document-request"
          element={
            <ProtectedRoute roles={['student', 'alumni']}>
              <DocumentRequest />
            </ProtectedRoute>
          }
        />
        <Route
          path="/document-tracking"
          element={
            <ProtectedRoute roles={['student', 'alumni']}>
              <DocumentTracking />
            </ProtectedRoute>
          }
        />
        <Route
          path="/payment"
          element={
            <ProtectedRoute roles={['student', 'alumni']}>
              <Payment />
            </ProtectedRoute>
          }
        />
        <Route
          path="/payment/return"
          element={
            <ProtectedRoute roles={['student', 'alumni']}>
              <PaymentReturn />
            </ProtectedRoute>
          }
        />
        <Route
          path="/payment/mock/gcash"
          element={
            <ProtectedRoute roles={['student', 'alumni']}>
              <PaymentMock />
            </ProtectedRoute>
          }
        />
        <Route
          path="/payment/mock/maya"
          element={
            <ProtectedRoute roles={['student', 'alumni']}>
              <PaymentMock />
            </ProtectedRoute>
          }
        />
        <Route
          path="/payment/receipt"
          element={
            <ProtectedRoute roles={['student', 'alumni']}>
              <PaymentReceipt />
            </ProtectedRoute>
          }
        />
        <Route
          path="/my-requests"
          element={
            <ProtectedRoute roles={['student', 'alumni']}>
              <RequestTracking />
            </ProtectedRoute>
          }
        />
      </Routes>
    </BrowserRouter>
  );
}

export default App;
